mapper.select:
/* BmsBcrNoCargoMapper.selectBcrNoCargoList : BCR 무적 조회 : BCR 무적 조회 */
SELECT SERIAL, SCAN_NO, SCAN_RESULT, SCAN_DATE, SCAN_TIME, CHECK_YN, CHECK_REMARKS, (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = bc.REGISTER_USER_ID) AS REGISTER_USER_ID, REGISTER_DATE_TIME, (SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = bc.UPDATE_USER_ID) AS UPDATE_USER_ID, UPDATE_DATE_TIME FROM TB_BMS_BCR_CHECK bc WHERE 1 = 1
AND SCAN_NO IN (#{item})
AND SCAN_NO = #{srchNo}
AND CHECK_YN = #{srchChangeClass}
AND ${srchDateGbn} >= #{srchStartDate} AND ${srchDateGbn} <= #{srchEndDate}
